Review this Kibana route for OAS compliance. A sibling route on the same resource has a deprecated property:

```typescript
// server/routes/agents.ts
router.versioned.put({
  path: '/api/agent_builder/agents/{agent_id}/access',
  summary: 'Update access control',
  description: 'Update the access control list for an agent.',
  options: {
    tags: ['access:agentBuilder', 'oas-tag:Agent builder'],
    availability: {
      stability: 'experimental',
      since: '9.5.0',
    },
  },
})
.addVersion(
  {
    version: '2023-10-31',
    validate: {
      request: {
        params: schema.object({
          agent_id: schema.string({
            meta: { description: 'The unique identifier of the agent.' },
          }),
        }),
        body: schema.object({
          entries: schema.arrayOf(
            schema.object({
              id: schema.maybe(schema.string({
                meta: {
                  description: 'The stable user profile ID.',
                  availability: { stability: 'experimental', since: '9.6.0' },
                },
              })),
              name: schema.maybe(schema.string({
                meta: {
                  description: 'Deprecated. Use id instead. Retained for backward compatibility.',
                },
              })),
              access_level: schema.oneOf(
                [schema.literal('read'), schema.literal('write'), schema.literal('admin')]
              ),
            })
          ),
        }),
      },
    },
    options: {
      oasOperationObject: () => path.join(__dirname, 'examples/agents_access_put.yaml'),
    },
  },
  handler
)
```
